  --mu-duration-fast: 250ms; /* incoming content, icon swap, dropdown and modal open, sliding indicator */
  --mu-duration-medium: 350ms; /* panel and toast close */
  --mu-duration-slow: 400ms; /* panel open, skeleton reveal */
  --mu-duration-gentle: 500ms; /* rare emphasis: text reveal, success */
  --mu-ease-out: cubic-bezier(0.22, 1, 0.36, 1); /* default: anything entering, and small swaps */
  --mu-ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1); /* things already on screen moving or crossfading out */
