.mu-type-display { font: 600 18px/24px var(--mu-sans); letter-spacing: -0.022em; }
.mu-type-content { font: 500 15px/20px var(--mu-sans); letter-spacing: -0.015em; }
.mu-type-title { font: 600 13.5px/18px var(--mu-sans); letter-spacing: -0.01em; }
.mu-type-lead { font: 500 13.5px/20px var(--mu-sans); letter-spacing: -0.01em; }
.mu-type-ui { font: 500 12.5px/16px var(--mu-sans); letter-spacing: -0.005em; }
.mu-type-body { font: 400 12.5px/18px var(--mu-sans); letter-spacing: -0.005em; }
.mu-type-meta { font: 400 11px/14px var(--mu-sans); letter-spacing: 0; }
.mu-type-label { font: 500 9px/12px var(--mu-mono); letter-spacing: 0.11em; font-stretch: var(--mu-mono-stretch); text-transform: uppercase; }
.mu-type-readout { font: 500 10.5px/14px var(--mu-mono); letter-spacing: 0.02em; font-stretch: var(--mu-mono-stretch); font-variant-numeric: tabular-nums; }
.mu-type-code { font: 400 10.5px/17px var(--mu-mono); letter-spacing: 0; font-stretch: var(--mu-mono-code-stretch); }
.mu-type-pixel { font: 700 40px/44px var(--mu-pixel); letter-spacing: 0; }

